# -*- coding: utf-8 -*-
S = {}

S["①"] = """貴校は学生620名の専修学校です。募集は年に一度の周期で回っており、その入口は募集説明会、そこから先の個別対応は担任が担っています。募集定員は所轄の手続きを経て確定し、確定した定員がその年度に受け入れられる人数の上限になります。上限が決まれば、納付金収入の上限もそこで決まります。そして、説明会に足を運んだ人の全員が入学するわけではないことは、貴校の名簿がそのまま示しています。学生数、説明会の回数、担任が動いた時間、確定した定員——この四つは、いずれも貴校の帳票の中にすでにある数字です。外から持ち込むものは、ここまで一つもありません。"""

S["②"] = """同じ材料を、人数ではなく時間の単位で数え直してみます。620名という数え方は、席に着いた人を数えたものです。これを「1名を席に着かせるまでに担任が使った時間」という単位に置き換えると、同じ一年が別の姿で見えてきます。説明会から入学まで到達しなかった人にも、担任の時間は同じだけ使われています。その時間は帳票に「使った工数」としては載りますが、「席に変わらなかった工数」としては分かれて載っていません。分けて数えたら、どれくらいの大きさになるでしょうか。いまの回し方で足りているのかどうかは、この単位で数え直すまでは、判断のしようがないように思われます。"""

S["③"] = """この、席に変わらなかった担任の時間に名前をつけます。「空席工数」と呼びます。そもそも空席工数とは、募集のために担任が投じた工数のうち、入学者という席に到達しなかった分を指す言葉です。これまで帳票に無かったのは、この言葉が無かったからであって、その作業が無かったからではありません。ただし、新しい呼び名だけでは起案者の机で止まります。既存の科目名に置き直します。教務主任の帳票では「担任工数」の内訳の一項目、理事長の帳票では「納付金収入」の取りこぼし分。呼び名は一つ、様式は二つ、指しているものは同じ一つです。"""

S["④"] = """なぜ今かは、2027年6月30日という日付で立ちます。この日を握っているのは都道府県私学担当課で、効く相手は専修学校という区分です（大学や高等専門学校には別の暦が当たります）。次年度の募集定員はこの日までに認可申請で確定させる必要があり、これは手続きの締切ではなく、決定そのものの締切です。制度の暦を事業の言葉に置き直します。次年度の認可申請までに確定していない募集定員は、概算30〜60（出所：貴校データ）。この分が確定しないまま日付を越えると、その席は次年度に存在せず、納付金収入もその分は最初から立ちません。しかも手続きは12か月周期で毎年繰り返すため、今年の未確定分は翌年の起点に持ち越されます。所轄庁の承認取り付けは当社実測で20〜45日（2件）、そこから逆算した着手期限は2026年12月28日。この逆算が、本件を本日起案する理由です。（貴校記入欄：本日時点の未確定定員＿＿名）"""

S["⑤"] = """他の進め方を、条件の形で開示します。現在の代理店への追加発注は、成果責任の範囲が契約書に定義されていないという条件の下では、支払が増えても結果の引受先が決まらない、という形になります。能力の話ではありません。分界表は三行です。媒体設計＝発注側の決定、制作＝受注側の実行、効果測定の判定基準＝未定義。三行目が空欄である限り、追加の金額は妥当性を判定できないまま積まれます。この段では当社の性能は申し上げません。他社の広告会社という選択肢は、同型の実名事例と価格構成（媒体費と制作費の内訳、人月単価）の両方が開示されない条件の下では、比較の土俵そのものが作れない、という形になります。なお当社は登録・認証の類を保有していません。購買の様式に置き直すと、追加発注は支払の妥当性を判定する行が空欄のまま、他社比較は価格構成が出るまで支払の可否を判定できない、となります。"""

S["⑥"] = """結論。媒体設計・制作・効果測定を一体で引き受け、空席工数を席に変える経路を6か月で組みます。金額320万〜480万円、着手2026年12月14日（着手期限の内側）。最初の3か月は媒体1本と効果測定だけの試行枠とし、3か月時点で打ち切れる区切りを契約に入れます。量は座席ごとに一つずつ置きます。教務主任へ：担任工数を年120〜240時間（月10〜20時間）ぶん効果測定側へ振り替え（現状値は貴校記入欄で確定）。理事長へ：支払は月53万〜80万円、前払いなし、手元資金からの流出は月次です。未確定定員30〜60のうち本提案が確定に寄与するのは18〜36、残る12〜24は学内の定員方針と担任の個別対応で決まり、本提案では動きません。浮いた分を実際に減らすのは理事長です。2027年4月1日の次年度予算で媒体費を減額。同じく2027年4月1日の次年度予算で業務委託費を減額。同意欄：媒体費□／業務委託費□（理事長署名＿＿）。前段で他社を外した条件は当社にも当てました。実名事例（△△学院大学、○○ストア株式会社）と価格構成は開示済み、成果責任の範囲は当社の契約書にも明記が無いため、上の分界表を契約書に添付して埋めます。同種の広告会社が並ぶ中で当社が残る根拠は、この二つだけです。想定反論：手元資金はいくら減るか→月53万〜80万円。効かなかったら→3か月で打ち切れます。保証は→成果の保証はしません、分界表の範囲で引き受けます。上申サマリ：6か月320万〜480万円、未確定定員30〜60のうち18〜36に対応。以上が、いま出せる材料の全部です。"""

BAN = ["消去","残余","カテゴリC","様相","必然化","問題化","内在的否定","措定","実然","前提化","共著者","蝶番","縮退","拘束の所在","エンテュメーメ","省略三段論法","外延","被覆率","M_0","M_i"]
for k,v in S.items():
    t = v.replace("\n","")
    hits = [b for b in BAN if b in t]
    print(k, len(t), "BAN:", hits)
